  const centre = (FIRE_WIDTH - 1) / 2
  const reach = 4 + (hash(dx, Math.floor(tick / 2)) % 2) - Math.abs(dx - centre) * 1.3
  if (height > reach) {
    return undefined
  }
  const heat =
    Math.abs(dx - centre) * 0.9 + (height >= reach - 0.5 ? 1 : 0) + (height === 1 ? 1 : 0)
  return FLAMES[Math.min(3, Math.floor(heat))]
}

